export function classify(event) {
  if (event === null || typeof event !== "object") {
    throw new TypeError("event must be a non-null object");
  }

  const kind = event.kind;
  let attempt = event.attempt ?? 0;

  if (!Number.isInteger(attempt) || attempt < 0) {
    throw new RangeError("attempt must be a non-negative integer");
  }

  let state;
  let terminal;
  let retryable;

  switch (kind) {
    case "start":
      state = "running";
      terminal = false;
      retryable = false;
      break;
    case "success":
      state = "done";
      terminal = true;
      retryable = false;
      break;
    case "retry":
      state = "waiting";
      terminal = false;
      retryable = attempt < 3;
      break;
    case "cancel":
      state = "cancelled";
      terminal = true;
      retryable = false;
      break;
    case "timeout":
      state = "failed";
      terminal = true;
      retryable = attempt < 3;
      break;
    case "error":
      state = "failed";
      terminal = true;
      retryable = false;
      break;
    case "pause":
      state = "paused";
      terminal = false;
      retryable = false;
      break;
    default:
      state = "unknown";
      terminal = false;
      retryable = false;
      break;
  }

  return { state, terminal, retryable };
}

