import { parseCents, formatMoney } from "./helper.mjs";
export function summarize(rows, currency) {
  if (!Array.isArray(rows)) {
    throw new TypeError("rows");
  }
  const accepted = [];
  let rejected = 0;
  let totalCents = 0;
  const balances = {};
  for (const row of rows) {
    if (row === null || typeof row !== "object" || Array.isArray(row)) {
      rejected += 1;
      continue;
    }
    const account = row.account;
    const amount = row.amount;
    if (typeof account !== "string" || account.trim() === "") {
      rejected += 1;
      continue;
    }
    const cents = parseCents(amount);
    if (cents === null) {
      rejected += 1;
      continue;
    }
    const name = account.trim();
    accepted.push(name);
    totalCents += cents;
    balances[name] = (balances[name] || 0) + cents;
  }
  const accounts = Object.keys(balances)
    .sort()
    .map((name) => ({
      account: name,
      balance: formatMoney({ cents: balances[name], currency }),
    }));
  return {
    accepted: accepted.length,
    rejected,
    total: formatMoney({ cents: totalCents, currency }),
    accounts,
  };
}
export const untouched = "keep";

